INSERT INTO p_amb_brand (act_id, slug, live, display_name, intro, about, audience, accent, logo_url, submit_platform, submit_url, submit_label, avoid_json, rules_json, season_json, show_inspo, pdf_json) VALUES ('act_hiden', 'hiden', 1, 'HIDEN', 'HIDEN makes clothes with two sides: normal on one, country on the other. You pick which one shows, and you can change your mind at the truck door. We want videos that look like your real week: the office, the school run, the lease, the tailgate, dinner with her parents. Pick an idea below, film it your way, and submit it on TRYBE.', 'Reversible everyday apparel from a real hunting brand. Black on one side, camo or the HIDEN print on the other, for men and women. The puffer leads; hoodies, vests and a women''s collection follow. Hidden details: a sunglasses-cleaning swatch sewn into the pocket, a chapstick pocket, a HIDEN keychain koozie, and a QR code on the tag that plays how your piece was made.', 'People who are country at heart and live a normal week: office jobs, school runs, date nights, with a lease, a boat or a tailgate on the weekend. From November we also talk to the wives, girlfriends and mums buying for him. The women''s collection talks to the country-concert and tailgate crowd.', '#E8401C', NULL, 'TRYBE', NULL, 'Film this on TRYBE', '[{"title": "Saying \"reversible\" or \"two looks, one jacket\" before you show it", "why": "Every outdoor brand says it. Flip the jacket on camera in the first three seconds instead; the flip is the whole idea."}, {"title": "Holding the jacket up on a hanger and listing features", "why": "A jacket on a hanger sells nothing. Wear it, flip it, go somewhere."}, {"title": "A talking-head review in your kitchen", "why": "We will get plenty. Take us to the two places the jacket lives: your normal day and your country one."}, {"title": "Making fun of city people or country people", "why": "The joke is that you are both. Nobody is the punchline."}, {"title": "Politics, \"redneck\", anything that picks a side", "why": "Camo already reads that way to some people. We are warm and funny about both sides of the jacket."}, {"title": "Claiming it is warmer, waterproof or scent-blocking", "why": "That is our hunt line''s job. This jacket sells on the flip and the details."}]', '["Flip the jacket on camera inside the first three seconds of every video. One move, no cut.", "You can say: \"made by a hunting brand\", \"two sides\", \"black side\", \"camo side\", \"there is a chapstick pocket\", \"there is a swatch to clean your sunglasses\", \"scan the tag to see how it was made\".", "Don''t say \"reversible\" or \"two looks, one jacket\" as your opener. Show it, then say it if you want.", "Don''t quote prices, discounts, a review count or a sales number. Only mention an offer that is live on the site the day you post.", "Don''t say \"sustainable\" or \"ethical\". If you scan the tag, describe what you saw, not what it proves.", "Show the camo side worn in at least one real place: the lease, the boat, the tailgate, the bonfire.", "Show the black side worn in at least one normal place: the office, the school run, dinner.", "If your partner is in it, they are in on the joke, never the nag.", "Film vertical, sound on, and show the jacket in the first second.", "Only film people who agreed to be in your video. If there is alcohol on screen, everyone is 21 or older. No weapons in frame."]', '{"title": "Deer season, tailgates and gift season", "until": "Dec 20", "line": "The first cold snap, opening day and tailgate Saturdays are here, and gift shopping starts in early November. Film your gift videos in October so they are ready for the holiday push.", "next": "Late winter cold and Father''s Day, from January", "highlight": ["10-01", "12-20"], "show_chart": true, "color": "#E8401C", "cap": null, "mode": "custom", "custom": {"1": 30, "2": 28, "3": 26, "4": 24, "5": 24, "6": 24, "7": 24, "8": 22, "9": 20, "10": 18, "11": 18, "12": 18, "13": 16, "14": 16, "15": 16, "16": 16, "17": 16, "18": 16, "19": 16, "20": 18, "21": 20, "22": 24, "23": 30, "24": 36, "25": 20, "26": 14, "27": 12, "28": 12, "29": 12, "30": 12, "31": 12, "32": 14, "33": 16, "34": 20, "35": 24, "36": 28, "37": 30, "38": 32, "39": 36, "40": 40, "41": 44, "42": 46, "43": 48, "44": 50, "45": 56, "46": 64, "47": 72, "48": 100, "49": 90, "50": 84, "51": 76, "52": 40, "53": 30}}', 1, '{"line1": "HIDEN creators,", "line2": "here''s what to film.", "intro": "Our creator hub has every idea we want right now: this week''s hot picks, the season, gift videos, openers you can say word for word, and the videos that worked. It updates on its own, so check it before you shoot.", "cta": "Your creator hub", "note": "Opens right on your phone. No login, no app.", "steps": ["Open the hub and pick an idea", "Film it in your real week, starting with the flip", "Submit on TRYBE with the idea''s name"]}');
