INSERT INTO p_amb_section (id, act_id, name, line, icon, icon_svg, color, enabled, pinned, sort) VALUES ('6c0435e0f5995f15', 'act_hiden', 'Made by hunters', 'Our hunters vouch for the flip. Real stands, real camo.', 'trees', '<path d="M10 10v.2A3 3 0 0 1 8.9 16H5a3 3 0 0 1-1-5.8V10a3 3 0 0 1 6 0Z"/><path d="M7 16v6"/><path d="M13 19v3"/><path d="M12 19h8.3a1 1 0 0 0 .7-1.7L18 14h.3a1 1 0 0 0 .7-1.7L16 9h.2a1 1 0 0 0 .8-1.7L13 3l-1.4 1.5"/>', '#15803D', 1, 0, 4);
INSERT INTO p_amb_section (id, act_id, name, line, icon, icon_svg, color, enabled, pinned, sort) VALUES ('ddc203ad33068434', 'act_hiden', 'The story', 'The QR code on the tag plays how your piece was made.', 'qr-code', '<rect width="5" height="5" x="3" y="3" rx="1"/><rect width="5" height="5" x="16" y="3" rx="1"/><rect width="5" height="5" x="3" y="16" rx="1"/><path d="M21 16h-3a2 2 0 0 0-2 2v3"/><path d="M21 21v.01"/><path d="M12 7v3a2 2 0 0 1-2 2H7"/><path d="M3 12h.01"/><path d="M12 3h.01"/><path d="M12 16v.01"/><path d="M16 12h1"/><path d="M21 12v.01"/><path d="M12 21v-1"/>', '#1D4ED8', 1, 0, 5);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('8be8466cfebe5d8b', 'act_hiden', '6a2b1ea957cf3953', 1, 1, 1, 'live', 'The flip', 'One jacket does your whole day. Black for the office, camo for the lease, and you flip it at the truck door.', 'The guy who is in a meeting at two and a deer stand at five.', 'Reversible puffer (men''s or women''s)', 'One take', 'Identity', '["Watch what happens to this jacket when I leave the office.", "Normal for now. Give it about four seconds.", "Same jacket. Two very different afternoons."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Start in the normal place: parking lot, office door, driveway. Black side out."}, {"label": "Middle", "text": "Flip it on camera in one move. Don''t cut. Let us see the camo come out."}, {"label": "Close", "text": "Walk into the country side of your day. One line about where you''re headed."}]', 'Normal for now. Country whenever.', 'Keep the flip in one continuous take. The reveal is the ad.', 'Explain what reversible means. Show it.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('96a2ba8bf38f9af4', 'act_hiden', '8be8466cfebe5d8b', 'inspo', 'https://cdn.tryatria.com/adfiles/m1464063157683037_Od3bhBWhq1I.mp4', 'https://cdn.tryatria.com/adfiles/m1464063157683037_y_SmTLnWrXU.jpeg', 'Burlebo', '"From the office to date night." Ran over a year. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('0d9abdc6dad3b56a', 'act_hiden', '6a2b1ea957cf3953', 1, 2, 2, 'live', 'She said no camo at dinner', 'Every couple has had the "you are not wearing that" conversation. This jacket ends it.', 'Couples. He wears camo everywhere; she has rules about where.', 'Reversible puffer (men''s or women''s)', 'Skit', 'Humor', '["She said no camo at her parents'' place. So I flipped it.", "\"You''re not wearing that.\" Okay. Watch this.", "She wanted black. I wanted camo. We both won."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Film the look she gives you at the door. Let her say the line in her own words."}, {"label": "Middle", "text": "Flip it right there in front of her. Keep her reaction in."}, {"label": "Close", "text": "Her verdict on camera. Then, later, the camo side back out when she''s not looking."}]', 'No camo at dinner. Fine.', 'Let her be funny. She is in on the joke.', 'Make her the nag or him the idiot. Both of them win.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('7145f71e8f87caf6', 'act_hiden', '0d9abdc6dad3b56a', 'inspo', 'https://cdn.tryatria.com/adfiles/m3737954816510088_5JPj_4Z2W_A.mp4', 'https://cdn.tryatria.com/adfiles/m3737954816510088_BpX5z3S0RF8.jpeg', 'Duck Camp', 'A day in the field with friends, phone-shot, laughs kept in. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('cb3ba5021c850b22', 'act_hiden', '6a2b1ea957cf3953', 1, 3, 3, 'live', 'Things you find after you buy it', 'The jacket has secrets: a swatch to clean your sunglasses, a chapstick pocket, a koozie on the keys, and a whole other side.', 'Anyone who likes a jacket with more going on than it shows.', 'Reversible puffer (men''s or women''s)', 'Fast cuts', 'Proof', '["It took me a week to find everything in this jacket.", "There''s a thing in here to clean your sunglasses. Who does that?", "Chapstick pocket. Koozie on the keys. And that''s before you flip it."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Find one detail on camera like you didn''t know it was there. Use it: wipe the sunglasses."}, {"label": "Middle", "text": "Fast cuts, one detail per cut: chapstick out of the pocket, koozie clipped on, the tag."}, {"label": "Close", "text": "End on the flip, like the biggest secret was the whole other side."}]', 'More than meets the eye', 'Actually use each detail. Wipe the glasses, open the chapstick.', 'List them in a caption. Show them.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('67200676bab1b2cd', 'act_hiden', 'cb3ba5021c850b22', 'inspo', 'https://cdn.tryatria.com/adfiles/m26982859624636820_YJIOyUjQa6I.mp4', 'https://cdn.tryatria.com/adfiles/m26982859624636820_YJu_zTRLAc0.jpeg', 'Duck Camp', 'One feature per cut, hands on the garment, no hanger. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('e5ed83bffe18fdf5', 'act_hiden', '6a2b1ea957cf3953', 1, 4, 4, 'live', 'He does not need another hoodie', 'Every December he gets another hoodie. This year he gets two jackets in one, and she likes him in both.', 'Wives, girlfriends and mums buying for a guy who owns camo and a job. Turn Hot in November.', 'Reversible puffer (men''s or women''s)', 'Voiceover', 'Gifting', '["Every year he gets a hoodie. This year he''s getting two jackets in one.", "If your husband owns camo and a job, this is the gift.", "I got him this so he''d stop wearing the other thing to dinner."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Talk to the camera like you''re telling a friend what you''re getting him."}, {"label": "Middle", "text": "Show him opening it and flipping it. His reaction is the ad."}, {"label": "Close", "text": "One line on where he wore it that week."}]', 'Two looks. One gift.', 'Film his real reaction. Keep the camera on his face.', 'Quote a price or a discount.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('06fe84484871bfe2', 'act_hiden', 'e5ed83bffe18fdf5', 'inspo', 'https://cdn.tryatria.com/adfiles/m3899531160297512_aBuJRp5S7No.mp4', 'https://cdn.tryatria.com/adfiles/m3899531160297512_xdbAlMk6Vwk.jpeg', 'Leni Swims', '"2 sets in 1", a creator wearing both sides. Ran over a year and a half. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('69283c7a45bf9992', 'act_hiden', 'e5ed83bffe18fdf5', 'inspo', 'https://cdn.tryatria.com/adfiles/m2061609167723470_bxZq4TgnioQ.mp4', 'https://cdn.tryatria.com/adfiles/m2061609167723470_hy6pwHqF6Ks.jpeg', 'Duck Camp', 'Gift guide told by the people who wear it, for Father''s Day. Steal the shape, not the brand.', 1, 2);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('aeb789ed4731e814', 'act_hiden', 'dccb18239753ba5c', 0, 0, 1, 'live', 'Unboxing, no gushing', 'Open the box, pull it out black side first, flip it, and be picky about the pockets and the zipper.', 'Day one. Every ambassador gets a box.', 'Reversible puffer (men''s or women''s)', 'Unboxing', 'Proof', '["It came. Let''s see if the camo side is real.", "Opening a jacket that''s supposedly two jackets. I''ve got questions.", "First look, no filter. Then I''m flipping it."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Open the box, pull it out black side first, say your honest first impression."}, {"label": "Middle", "text": "Flip it. Show the seams, the pockets on both sides, the zipper. Be picky."}, {"label": "Close", "text": "Put it on and say which side you''d wear today."}]', 'First look', 'Check the pockets on both sides on camera. People worry about that with reversibles.', 'Spend the first seconds on the lid.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('5178aa0da8133e88', 'act_hiden', 'aeb789ed4731e814', 'inspo', 'https://cdn.tryatria.com/adfiles/m1233143850715181_eOXrg4BvGao.mp4', 'https://cdn.tryatria.com/adfiles/m1233143850715181_gidrCXE3Roc.jpeg', 'Burlebo', 'A jacket launch told straight to camera, honest about last year selling out. Ran 222 days. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('f4f83f85d5906a7f', 'act_hiden', 'dccb18239753ba5c', 0, 0, 2, 'live', 'One jacket, one whole day', 'One jacket, six places, flipped every time the setting changes.', 'The person whose Saturday goes from a kid''s game to a bonfire.', 'Reversible puffer (men''s or women''s)', 'Day in the life', 'Identity', '["One jacket. Six places. Let''s go.", "Soccer game, Lowe''s, the lease, dinner. Same jacket, different side.", "Counting how many times I flip this thing today."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Clip at the first stop, two seconds. Say where you are."}, {"label": "Middle", "text": "Flip it on camera every time the setting changes. Put a count on screen."}, {"label": "Close", "text": "End with the total and which side won the day."}]', 'Flips today: 4', 'Keep a running count on screen.', NULL, NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('d17b67bef40074bd', 'act_hiden', 'f4f83f85d5906a7f', 'inspo', 'https://cdn.tryatria.com/adfiles/m1464063157683037_Od3bhBWhq1I.mp4', 'https://cdn.tryatria.com/adfiles/m1464063157683037_y_SmTLnWrXU.jpeg', 'Burlebo', '"From the office to date night." Ran over a year. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('b3a7b876fee5716c', 'act_hiden', 'dccb18239753ba5c', 0, 0, 3, 'live', 'My buddies when the camo came out', 'Show up in a plain black jacket, flip it, and film the table.', 'Anyone whose friends have opinions.', 'Reversible puffer (men''s or women''s)', 'Reaction', 'Status', '["Showed up in a plain black jacket. Then I flipped it. Listen to these guys.", "My buddy called it a gimmick. Then he asked where I got it.", "Sound on. Watch the table when this thing turns inside out."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Start recording before the flip, with your group in frame."}, {"label": "Middle", "text": "Flip it and keep the camera on them, not you."}, {"label": "Close", "text": "Get the loudest one''s verdict. Then let him try it on."}]', 'Wait for it', 'Keep the reaction real. One take, no script for your buddies.', NULL, NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('7a4689b8b75178b2', 'act_hiden', 'b3a7b876fee5716c', 'inspo', 'https://cdn.tryatria.com/adfiles/m3737954816510088_5JPj_4Z2W_A.mp4', 'https://cdn.tryatria.com/adfiles/m3737954816510088_BpX5z3S0RF8.jpeg', 'Duck Camp', 'A day in the field with friends, phone-shot, laughs kept in. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('080bc506ce6c3cc8', 'act_hiden', 'dccb18239753ba5c', 0, 0, 4, 'live', 'Thirty days in', 'A month in, say which side you actually wear, what bugs you, and whether it stays.', 'Every ambassador, a month after the box shows up. The second video from one piece.', 'Any HIDEN reversible piece', 'Update', 'Proof', '["Thirty days with the flip jacket. Honest update.", "Which side I actually wear, a month in.", "What I like, what bugs me, and whether I''d buy it."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Show it after a month, marks and all. Say how many days it''s been worn."}, {"label": "Middle", "text": "Say which side got more days and why. One thing that annoyed you."}, {"label": "Close", "text": "Say whether it stays in the rotation."}]', '30 days in', 'Be honest about which side wins. That is more believable than pretending.', NULL, NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('06f95c92e359ae37', 'act_hiden', '080bc506ce6c3cc8', 'inspo', 'https://cdn.tryatria.com/adfiles/m1257271578221790_yQeJITlwPCE.mp4', 'https://cdn.tryatria.com/adfiles/m1257271578221790_FnvxU5UF2lc.jpeg', 'Burlebo', '"One of our most common questions, answered." Ran 551 days. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('434bb4b4e7672fdc', 'act_hiden', 'dccb18239753ba5c', 0, 0, 5, 'live', 'Which side are you', 'A question, not a pitch: black side or camo side on a Tuesday?', 'The comment section.', 'Reversible puffer (men''s or women''s)', 'Question', 'Belonging', '["Black side or camo side. Which one are you on a Tuesday?", "Be honest. Which side would you wear to work?", "My wife says black. I say camo. Settle it."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Hold up both sides, flip once, ask the question straight to camera."}, {"label": "Middle", "text": "Show each side worn for two seconds."}, {"label": "Close", "text": "Say which one you are and tell people to argue in the comments."}]', 'Black side or camo side?', 'Ask it like you actually want the answer.', NULL, NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('9840f4f35ffb612d', 'act_hiden', '434bb4b4e7672fdc', 'inspo', 'https://cdn.tryatria.com/adfiles/m1257271578221790_yQeJITlwPCE.mp4', 'https://cdn.tryatria.com/adfiles/m1257271578221790_FnvxU5UF2lc.jpeg', 'Burlebo', '"One of our most common questions, answered." Ran 551 days. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('dd1effdb3cf0697d', 'act_hiden', 'b0060145302c92c9', 0, 0, 1, 'live', 'Opening day, straight from work', 'Leave the office at noon, flip it in the truck, and you are at the gate without changing.', 'The guy who takes a half day on opening day.', 'Reversible puffer (men''s or women''s)', 'One take', 'Identity', '["Left the office at noon. Didn''t change jackets. Here''s how.", "Opening day. Flipped it in the truck. Let''s go.", "Nobody at work knows what the inside of this jacket looks like."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Clip the office or the parking lot, black side out."}, {"label": "Middle", "text": "Flip it in the truck. Show the drive, the gate, the stand."}, {"label": "Close", "text": "One line at the end about how the afternoon went."}]', 'Opening day, straight from work', NULL, 'Show a weapon in frame.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('4452199daa68d543', 'act_hiden', 'dd1effdb3cf0697d', 'inspo', 'https://cdn.tryatria.com/adfiles/m3737954816510088_5JPj_4Z2W_A.mp4', 'https://cdn.tryatria.com/adfiles/m3737954816510088_BpX5z3S0RF8.jpeg', 'Duck Camp', 'A day in the field with friends, phone-shot, laughs kept in. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('48eb75088ea3c2fb', 'act_hiden', 'b0060145302c92c9', 0, 0, 2, 'live', 'The gift I''d actually want', 'The ask comes from him, not the brand: if somebody asks what to get you, send them this.', 'The guy whose family asks every year and gets socks.', 'Reversible puffer (men''s or women''s)', 'Voiceover', 'Gifting', '["If somebody asks what to get you this year, send them this.", "Please stop buying me socks. Buy me this.", "My wife asked what I wanted. I flipped the jacket and said \"this, both sides.\""]', '[{"label": "Open \u00b7 0 to 3s", "text": "Talk to camera like it''s your family asking."}, {"label": "Middle", "text": "Flip it once so they get it. Show a detail or two."}, {"label": "Close", "text": "Say where to find it. Done."}]', 'Send this to whoever asks', 'Pair with "He does not need another hoodie" so both sides of the gift are covered.', NULL, NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('a24fb82f86316323', 'act_hiden', '48eb75088ea3c2fb', 'inspo', 'https://cdn.tryatria.com/adfiles/m2061609167723470_bxZq4TgnioQ.mp4', 'https://cdn.tryatria.com/adfiles/m2061609167723470_hy6pwHqF6Ks.jpeg', 'Duck Camp', 'Gift guide told by the people who wear it, for Father''s Day. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('8ef26c9316fa49a4', 'act_hiden', 'b0060145302c92c9', 0, 0, 3, 'live', 'Tailgate to the game', 'Camo for the tailgate, black for the bar, and you never went home to change.', 'Anyone whose Saturday is a parking lot, then a stadium, then a bar.', 'Reversible puffer or hoodie', 'Transition', 'Belonging', '["Camo for the tailgate, black for the bar. One jacket.", "Three places, one Saturday, and I never went home to change.", "This jacket has a tailgate side."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Tailgate clip, camo out, cooler in frame. Koozie on the keys if you''ve got it."}, {"label": "Middle", "text": "Flip it walking in. Show the black side in the stands or at the bar."}, {"label": "Close", "text": "One line: never went home to change."}]', 'Never went home to change', 'Everyone on screen with a drink is 21 or older.', NULL, NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('196c845cdb9ccd32', 'act_hiden', '8ef26c9316fa49a4', 'inspo', 'https://cdn.tryatria.com/adfiles/m3737954816510088_5JPj_4Z2W_A.mp4', 'https://cdn.tryatria.com/adfiles/m3737954816510088_BpX5z3S0RF8.jpeg', 'Duck Camp', 'A day in the field with friends, phone-shot, laughs kept in. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('20ae6f5407a7411c', 'act_hiden', '07f2d4d7b6fb6c2f', 0, 0, 1, 'draft', 'Work fit, concert fit, same jacket', 'Nine to five on one side, the show on the other, and she never changed jackets.', 'The woman with a concert on Friday and a job on Friday morning.', 'Women''s reversible puffer', 'GRWM', 'Identity', '["Get ready with me for work. Then watch me get ready for the show without changing jackets.", "Nine to five on one side. The show on the other.", "I have one jacket for the office and the concert and it''s the same jacket."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Morning: black side, the work outfit, out the door."}, {"label": "Middle", "text": "Evening: flip it on camera, boots on, show the print side with the night outfit."}, {"label": "Close", "text": "One line about which side got more compliments."}]', 'Work fit. Concert fit. Same jacket.', NULL, NULL, NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('181f46bda7dab079', 'act_hiden', '20ae6f5407a7411c', 'inspo', 'https://cdn.tryatria.com/adfiles/m974119848180315_Y-MMe23xxWI.mp4', NULL, 'Comfrt', 'A creator haul of a camo hoodie: "I have zero self-control... I will be living in them all winter." Steal the voice, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('50bf2d0ac11baeba', 'act_hiden', '07f2d4d7b6fb6c2f', 0, 0, 2, 'draft', 'The set', 'A matching set with two sides is four outfits, and she will be living in it all winter.', 'The matching-set buyer who already owns four sets.', 'Reversible sweat set or jumpsuit', 'Try-on', 'Value', '["I have zero self-control and this set has two sides, so that''s four outfits.", "Camo side for the bonfire. Print side for the airport. Same set.", "I will be living in this all winter. Both sides."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Try on the first side, say how it feels. Pockets, cuffs, the hood."}, {"label": "Middle", "text": "Flip the top and the bottoms on camera. Show the second side worn."}, {"label": "Close", "text": "Say which side you''re wearing out the door today."}]', 'Four outfits. One set.', NULL, NULL, NULL);
