INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('5561bb7e5c24a72f', 'act_hiden', '07f2d4d7b6fb6c2f', 0, 0, 3, 'draft', 'Not pink. Not boxy. Mine.', 'Camo cut for a woman: the waist, the sleeves, the hood, on both sides.', 'The woman who has been handed a men''s small with a pink zipper one too many times.', 'Women''s reversible puffer', 'Try-on', 'Relief', '["Finally, camo that isn''t a men''s small with a pink zipper.", "They cut this for a woman. You can tell at the waist.", "Camo side, black side, and it actually fits. Watch."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Show the fit on both sides: waist, sleeves, hood. Turn around."}, {"label": "Middle", "text": "Flip it and show it still fits on the other side."}, {"label": "Close", "text": "Say what you usually have to settle for."}]', 'Cut for her. Both sides.', NULL, 'Call anything pink or cute. That is the thing she is sick of.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('d5cfb5f83f8d556e', 'act_hiden', '5561bb7e5c24a72f', 'inspo', 'https://cdn.tryatria.com/adfiles/m974119848180315_Y-MMe23xxWI.mp4', NULL, 'Comfrt', 'A creator haul of a camo hoodie: "I have zero self-control... I will be living in them all winter." Steal the voice, not the brand.', 1, 1);
