INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('0801e1fb38ed96da', 'act_hiden', '6c0435e0f5995f15', 0, 0, 1, 'live', 'We make hunt gear. This is the rest of the week.', 'A real hunter in HIDEN hunt gear in the stand, then the same person in town in the reversible.', 'HIDEN''s current hunters, and anyone who worries a camo fashion brand is a costume.', 'Reversible puffer plus your HIDEN hunt gear', 'Transition', 'Proof', '["I''ve hunted in HIDEN for three seasons. This is what they made for the other six days.", "Same camo I wear in the stand. Now it''s got a side I can wear to work.", "This isn''t a fashion brand that found camo. It''s a hunting brand that found Monday."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Show your HIDEN hunt gear, worn, in the field."}, {"label": "Middle", "text": "Cut to town: same person, the reversible, black side out. Flip it."}, {"label": "Close", "text": "Say why it matters that the same brand made both."}]', 'Made by hunters', 'Only film this if you actually hunt in HIDEN gear.', 'Show a weapon in frame.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('711997acdb793509', 'act_hiden', '0801e1fb38ed96da', 'inspo', 'https://cdn.tryatria.com/adfiles/m1159079752828028_BvprWCbAQa0.mp4', 'https://cdn.tryatria.com/adfiles/m1159079752828028_lTv095e462Y.jpeg', 'Duck Camp', 'The thing you wear carries the story of where you wore it. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('913c3ee0e7f8efbd', 'act_hiden', '6c0435e0f5995f15', 0, 0, 2, 'live', 'Is the camo real', 'Flip to camo, walk into the tree line, and let the pattern prove itself.', 'The skeptic who assumes a lifestyle camo is a print, not a pattern.', 'Reversible puffer (men''s or women''s)', 'Test', 'Proof', '["Is this fashion camo or real camo? Let''s go stand in the woods and find out.", "Flipped it to the camo side and walked into the tree line. Can you see me?", "Same pattern as their hunt line. I checked."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Flip to camo on camera at the edge of the woods."}, {"label": "Middle", "text": "Walk in, have someone film from twenty yards. Let it blend."}, {"label": "Close", "text": "Walk out, flip back to black, say what you think."}]', 'Can you see me?', 'Confirm with the brand that the reversible uses the real Exile pattern before filming this.', NULL, NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('4ea0b05cb2f1fb3c', 'act_hiden', '913c3ee0e7f8efbd', 'inspo', 'https://cdn.tryatria.com/adfiles/m3737954816510088_5JPj_4Z2W_A.mp4', 'https://cdn.tryatria.com/adfiles/m3737954816510088_BpX5z3S0RF8.jpeg', 'Duck Camp', 'A day in the field with friends, phone-shot, laughs kept in. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('d94c18e52cb8972d', 'act_hiden', 'ddc203ad33068434', 0, 0, 1, 'live', 'Scan the tag', 'The QR code on the tag plays how the piece was made, farm to finished jacket.', 'The buyer who wants to know who made it. Best for people who already know the brand.', 'Any HIDEN reversible piece', 'Screen record', 'Proof', '["There''s a QR code on the tag. I scanned it. Did not expect this.", "This jacket has a whole movie about where it came from.", "Scan the tag. Meet the people who made it."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Find the tag, scan it on camera, show the phone."}, {"label": "Middle", "text": "Screen-record ten seconds of the story: the farm, the sewing."}, {"label": "Close", "text": "Say one thing you learned. Then flip the jacket."}]', 'Scan the tag', NULL, 'Say "sustainable" or "ethical". Describe what you saw.', NULL);
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, url, thumb, who, note, shown, sort) VALUES ('366e79fbbe52e875', 'act_hiden', 'd94c18e52cb8972d', 'inspo', 'https://cdn.tryatria.com/adfiles/m1159079752828028_BvprWCbAQa0.mp4', 'https://cdn.tryatria.com/adfiles/m1159079752828028_lTv095e462Y.jpeg', 'Duck Camp', 'The thing you wear carries the story of where you wore it. Steal the shape, not the brand.', 1, 1);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend) VALUES ('701997d5416e6f2a', 'act_hiden', 'ddc203ad33068434', 0, 0, 2, 'draft', 'Good clothes do good things', 'Part of every piece goes somewhere. Show the receipt.', 'The buyer who picks the brand that gives back. Only once the program is real and documented.', 'Any HIDEN reversible piece', 'Voiceover', 'Belonging', '["Here''s where part of this jacket went.", "I bought a jacket. Somebody else got something they needed.", "Good clothes do good things. Here''s the receipt."]', '[{"label": "Open \u00b7 0 to 3s", "text": "Show the piece and say what the brand does with part of the sale."}, {"label": "Middle", "text": "Show it: the delivery, the drive, the people, whatever HIDEN can document."}, {"label": "Close", "text": "Flip the jacket. One line."}]', 'Good clothes do good things', 'Film only what the brand can show you really happened.', NULL, NULL);
